sp_widget.client_script:
function($scope, $rootScope, spUtil, $timeout) {
  $scope.anoSelecionado = "";
  $scope.dadosVisiveis = null;
  $scope.isFading = false;

  function carregarDados(ano) {
    $scope.isFading = true;
    $timeout(function() {
      if (ano === '' || ano == null) {
        $scope.dadosVisiveis = null;
        $scope.isFading = false;
        return;
      }

      spUtil.get('widget_despesas_porcentagem_ano', { filtro_ano: ano }).then(function(response) {
        if (response.data && response.data.dados && response.data.dados.length > 0) {
          $scope.dadosVisiveis = response.data.dados[0];
        } else {
          $scope.dadosVisiveis = null;
        }
        $scope.isFading = false;
      });
    }, 500);
  }

  $rootScope.$on('anoSelecionado', function(evt, ano) {
    $scope.anoSelecionado = ano;
    carregarDados(ano);
  });

  carregarDados(new Date().getFullYear());
}

sp_widget.css:
/* --- 1. Importação da Fonte --- */
@import url('https://fonts.googleapis.com/css2?family=Roboto+Flex:opsz,wght@8..144,100..1000&display=swap');

/* --- 2. Wrapper Principal (Controla Animação e Layout Externo) --- */
.financial-widget-wrapper {
  font-family: 'Roboto Flex', sans-serif;
  margin-top: 4rem; /* Padronizado com o Widget 2 */

  /* Propriedades de Transição */
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
  transition: opacity 0.5s ease-in-out, transform 0.5s ease-in-out, visibility 0.5s ease-in-out;
}

/* Estado quando o widget está recarregando (Fade Out) */
.financial-widget-wrapper.fade-out {
  opacity: 0;
  visibility: hidden;
  transform: translateY(20px);
}

/* --- 3. Estrutura do Widget --- */
.financial-widget {
  border: 1px solid #ccc;
  border-radius: 4px;
  overflow: hidden;
  background-color: #fff; /* Garante fundo branco */
}

.indicator-block {
  text-align: center;
  padding: 0;
}

.indicator-header {
  background-color: #EBEDF1;
  color: #021770; /* Azul padrão do Widget 2 */
  font-weight: 400;
  padding: 8px 10px;
  font-size: 14px;
  border-bottom: 1px solid #C7C7C7;
  font-family: 'Roboto Flex', sans-serif;
}

.indicator-value {
  color: #021770; /* Azul padrão do Widget 2 */
  font-size: 32px;
  font-weight: 400;
  padding: 10px 10px 15px;
  font-family: 'Roboto Flex', sans-serif;
}

/* Classe utilitária para quando a mensagem for texto (sem dados) */
.indicator-value.small-text {
  font-size: 18px;
  color: #666;
  line-height: 1.5;
  padding: 20px;
}

/* --- 4. Responsividade --- */

/* Telas Pequenas (Mobile - até 767px) */
@media (max-width: 767px) {
  .financial-widget-wrapper {
    margin-top: 1rem;
  }

  .indicator-value {
    font-size: 24px;
  }
}

/* Tablets (768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  .financial-widget-wrapper {
    margin-top: 2rem;
  }
}

/* Galaxy Z Fold 5 e dispositivos muito estreitos */
@media (max-width: 350px) {
  .indicator-header {
    font-size: 12px;
  }
  .indicator-value {
    font-size: 20px;
    padding: 6px;
  }
}

sp_widget.script:
(function() {
  /*function formatarNumero(valor, divisor, sufixo) {
    //var resultado = (valor / divisor).toFixed(3); // fixa 3 casas
    // insere separador de milhar com expressão regular
		var resultado = (valor / divisor); // fixa 3 casas
    resultado = resultado.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
    return resultado + ' ' + sufixo;
  }*/

	  function formatarNumero(valor) {
        if (typeof valor !== 'number') {
            valor = parseFloat(valor);
        }

        return valor.toFixed(2) // fixa duas casas decimais
                    .replace('.', ',') // troca ponto decimal por vírgula
                    .replace(/\B(?=(\d{3})+(?!\d))/g, '.'); // insere separadores de milhar
    }


  var anoFiltrado = (typeof input !== 'undefined' && input.filtro_ano) ? input.filtro_ano : '';
  var gr = new GlideRecord('x_sded9_portal_t_0_u_despesa_pessoal');

  if (anoFiltrado) {
    gr.addQuery('u_ano', anoFiltrado);
  }

  gr.orderByDesc('u_ano');
  gr.query();

  var dados = [];
  while (gr.next()) {
    var despesaLiquida = parseFloat(gr.getValue('u_despesa_liquida_pedidos')) || 0;

    var valorFormatado;
    if (despesaLiquida >= 1) {
      valorFormatado = formatarNumero(despesaLiquida);
    } else {
      valorFormatado = formatarNumero(despesaLiquida);
    }

    dados.push({
      ano: gr.getValue('u_ano'),
      despesaLiquida: despesaLiquida,
      receitaCorrente: parseFloat(gr.getValue('u_receita_corrente_liquida')) || 0,
      comprometimento: parseFloat(gr.getValue('u_comprometimento_rcl')) || 0,
      limiteAlerta: parseFloat(gr.getValue('u_limite_de_alerta')) || 0,
      limitePrudencial: parseFloat(gr.getValue('u_limite_prudencial')) || 0,
      limiteMaximo: parseFloat(gr.getValue('u_limite_maximo')) || 0,
      valorDespesaFormatado: valorFormatado
    });
  }

	//gs.addInfoMessage(JSON.stringify(dados))

  data.dados = dados;
})();
